/// <summary>
/// The <c>METPurchaseOrderInvoicedBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide purchase order change request business event.
/// Task 305538: PB033 -CB492 - PO status 'Invoiced is not appearing in Abbyy Open PO table (Bug - 290169) - D365 Build
/// </summary>
[BusinessEvents(classStr(METPurchaseOrderInvoicedBusinessEventContract),
    "@MET:METPurchOrderInvoiceBE",
    "@MET:METPurchOrderInvoiceBEDescription",
    ModuleAxapta::PurchaseOrder)]
public final class METPurchaseOrderInvoicedBusinessEvent extends BusinessEventsBase
{
    private VendInvoiceJour vendInvoiceJour;
    private PurchTable      purchTable;  

}

Method.Source:
/// <summary>
/// Constructs a new METPurchaseOrderInvoicedBusinessEvent business event.
/// </summary>
/// <param name = "_vendPackingSlipJour">The <c>VendPackingSlipJour</c> record.</param>
/// <param name = "_purchTable">The <c>PurchTable</c> record.</param>
/// <returns>A new <c>METPurchaseOrderInvoicedBusinessEvent</c> business event.</returns>
public static METPurchaseOrderInvoicedBusinessEvent construct(
    VendInvoiceJour _vendInvoiceJour,
    PurchTable _purchTable)
{
    var event = new METPurchaseOrderInvoicedBusinessEvent();

    event.parmVendInvoiceJour(_vendInvoiceJour);
    event.parmPurchTable(_purchTable);

    return event;
}

/// <summary>
/// Overrides to provide purchase order confirmed data.
/// </summary>
/// <returns>The <c>METPurchaseOrderInvoicedBusinessEvent</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    var contract = METPurchaseOrderInvoicedBusinessEventContract::construct();

    contract.parmLegalEntity(vendInvoiceJour.DataAreaId);
    contract.parmPurchaseOrderNumber(vendInvoiceJour.PurchId);
    contract.parmVendorAccount(vendInvoiceJour.OrderAccount);
    contract.parmJournalId(vendInvoiceJour.InvoiceId);
    contract.parmInvoiceId(vendInvoiceJour.InvoiceId);
    contract.parmDocumentDate(vendInvoiceJour.DocumentDate);
    contract.parmPurchaseType(enum2Symbol(enumNum(PurchaseType), vendInvoiceJour.PurchaseType));
    contract.parmRequesterPersonnelNumber(this.getPersonnelNumberForWorker(purchTable.Requester));
    contract.parmRequesterName(this.getNameForWorker(purchTable.Requester));
    contract.parmWorkerPurchPlacerPersonnelNumber(this.getPersonnelNumberForWorker(purchTable.WorkerPurchPlacer));
    contract.parmWorkerPurchPlacerName(this.getNameForWorker(purchTable.WorkerPurchPlacer));
    contract.parmContactPersonId(purchTable.ContactPersonId);

    if (purchTable.ContactPersonId)
    {
        contract.parmEmail(purchTable.Email);
        contract.parmPhone(purchTable.contactPersonPhone());
    }
    else
    {
        var vendTable = purchTable.vendTable_OrderAccount();
        contract.parmEmail(vendTable.email());
        contract.parmPhone(vendTable.phone());
    }

    contract.parmModifiedDateTime(DateTimeUtil::getSystemDateTime());

    METPurchTable metPurchTable = METPurchTable::find(purchTable.PurchId);

    contract.parmPOChngSubMode(metPurchTable.POChngSubMode);
    contract.parmPOSubMode(metPurchTable.POSubMode);

    return contract;
}

/// <summary>
/// Gets the personnel number for the worker.
/// </summary>
/// <param name = "_workerRecId">HcmWorkerRecId</param>
/// <returns>Personnel number</returns>
private str getPersonnelNumberForWorker(HcmWorkerRecId _workerRecId)
{
    return HcmWorker::find(_workerRecId).PersonnelNumber;
}

/// <summary>
/// Gets the name for the worker.
/// </summary>
/// <param name = "_workerRecId">HcmWorkerRecId</param>
/// <returns>Name</returns>
private str getNameForWorker(HcmWorkerRecId _workerRecId)
{
    return HcmWorker::worker2Name(_workerRecId);
}

/// <summary>
/// Parameter method for VendInvoiceJour.
/// </summary>
/// <param name = "_vendInvoiceJour">VendInvoiceJour</param>
/// <returns>VendInvoiceJour</returns>
private VendInvoiceJour parmVendInvoiceJour(VendInvoiceJour _vendInvoiceJour = vendInvoiceJour)
{
    vendInvoiceJour = _vendInvoiceJour;

    return vendInvoiceJour;
}

/// <summary>
/// Parameter method for PurchTable.
/// </summary>
/// <param name = "_purchTable">PurchTable</param>
/// <returns>PurchTable</returns>
private PurchTable parmPurchTable(PurchTable _purchTable = purchTable)
{
    purchTable = _purchTable;

    return purchTable;
}

/// <summary>
/// Initializes the business event.
/// </summary>
private void new()
{
}

/// <summary>
/// Gets the record context for this event.
/// </summary>
/// <returns>The <c>PurchTable</c> buffer for the record context for this event.</returns>
public Common getContextRecord()
{
    return this.parmPurchTable();
}
